contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint val) public payable {
        uint beforeMinSum = c.MinSum(); if (__ESBMC_reverted()) return;

        bool setReverted;
        c.SetMinSum(val); bool __rev0 = __ESBMC_reverted(); if (__rev0) { setReverted = true; } else { setReverted = false; }

        uint afterSet = c.MinSum(); if (__ESBMC_reverted()) return;

        bool initReverted;
        c.Initialized(); bool __rev1 = __ESBMC_reverted(); if (__rev1) { initReverted = true; } else { initReverted = false; }

        uint afterInit = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(setReverted ? afterSet == beforeMinSum && afterInit == beforeMinSum : afterSet == val && afterInit == val);
    }
}

